argv:
$ErrorActionPreference='Stop'
$base='http://127.0.0.1:17448'
$state=Get-Content -LiteralPath 'E:\WebAIBridge\app\data\state.json' -Raw|ConvertFrom-Json
$cut=Get-Content -LiteralPath 'E:\WebAIBridge\app\data\projects-live-control-plane-cutover-r42.json' -Raw|ConvertFrom-Json
$cfg=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog?detect=0') -TimeoutSec 12
$life=Invoke-RestMethod -Uri ($base+'/api/operator-lifecycle') -TimeoutSec 12
$as=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog/agent-assignments') -TimeoutSec 12
$dry=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog/agent-assignments/dry-run') -TimeoutSec 15
if (([string](& git.exe -C 'E:\WebAIBridge' rev-parse HEAD)).Trim() -ne '66e2ca7681b5e4c4affde9641b69e5582b718f99') {throw 'BRIDGE_SHA_CHANGED'}
if($life.mode -ne 'RUNNING_ATTACH' -or $state.settings.paused -ne $false -or $cut.holdActive -ne $false) {throw 'OPERATOR_QUEUE_HOLD_BLOCKED'}
if($cfg.config.enabled -ne $true -or $cfg.config.mode -ne 'full' -or $cfg.config.allowAutonomousSend -ne $true -or $cfg.config.enforceHighMode -ne $true -or $cfg.config.maxParallelAgents -ne 1) {throw 'SEND_AUTHORITY_BLOCKED'}
if($cfg.config.autoContinueEnabled -ne $false -or $cfg.config.openExistingChatIfMissing -ne $false) {throw 'UNWANTED_BROWSER_AUTOMATION'}
if(@($as.assignments|Where-Object {$_.state -in @('queued','dispatching','running','awaiting_evidence','unknown')}).Count -ne 0) {throw 'UNSETTLED_ASSIGNMENTS_PRESENT'}
if($dry.dryRun -ne $true -or $dry.sendAttempted -ne $false -or $dry.replacementAttempted -ne $false -or $dry.openedClosedChats -ne $false) {throw 'PREFLIGHT_NOT_READONLY'}
$qa=@($cfg.config.managedChats|Where-Object {$_.enabled -eq $true -and $_.role -eq 'qa' -and $_.repository -eq 'foto6/boss'})
if($qa.Count -ne 1) {throw 'QA_NOT_UNIQUE'}
$row=@($dry.rows|Where-Object {$_.chatId -eq $qa[0].id})
if($row.Count -ne 1 -or $row[0].preflightAllowed -ne $true -or $row[0].preflightReason -ne 'ready' -or $row[0].openTabs -ne 1) {throw 'QA_CHAT_UNAVAILABLE'}
if(@($row[0].snapshots|Where-Object {$_.highMode -eq $true -and $_.generating -ne $true -and $_.providerLoadError -ne $true}).Count -ne 1){throw 'QA_HIGH_IDLE_NOT_PROVEN'}
$body=@{
 text="R65 AUTONOMY CANARY — QA, SINGLE ASSIGNMENT. You are the QA agent working ONLY in foto6/boss, on dedicated branch agent/qa-r65-autonomy-single-canary-20261014, exact starting head ea97137b3dd6077e9c330989a4e629a862e2cbf8. Do not reset or overwrite other branches; inspect current branch HEAD before edits and reconcile if changed. Independent task: verify R65/R66 bridge autonomy release claims with a meaningful, deterministic QA regression/test artifact and a short audit report, using the existing boss repository tests/patterns. Focus on R50 single-send authority gating, R65 global canary cap, current R66 read-only Windows launchers, refusal to replay UNKNOWN effects, preserving existing ChatGPT tabs, and distinction between mock safety tests and real live acceptance. You may add a narrowly scoped test in tests/ and a workflow specifically for THIS canary branch so the actual new commit has real GitHub CI evidence. Run relevant tests; commit and push only your dedicated branch; report exact new HEAD, changed paths, test counts, real workflow run ID and conclusion. If provider/API limits, GitHub workflow, project files, or exact branch authority prevent valid proof, report BLOCKED and DO NOT fake evidence. Never navigate or refresh old ChatGPT sessions to circumvent limits; no provider chat deletion, social publishing, PC safety changes, global sends, production WebAIBridge edits, or access to E:\\manhwa. Stop after this ONE milestone.";
 repository='foto6/boss';
 branch='agent/qa-r65-autonomy-single-canary-20261014';
 expectedHead='ea97137b3dd6077e9c330989a4e629a862e2cbf8';
 idempotencyKey='r65-qa-live-single-canary-20261014-gpt6-001';
 priority=500;
 evidenceTimeoutMinutes=120;
 supervisorVerificationRequired=$false
} | ConvertTo-Json -Compress -Depth 7
$u=$base+'/api/supervisor-watchdog/managed-chats/'+[uri]::EscapeDataString($qa[0].id)+'/assignments'
$r=Invoke-RestMethod -Method Post -Uri $u -Body $body -ContentType 'application/json' -TimeoutSec 15
if(-not $r.id){throw 'QUEUED_RESPONSE_NO_ID'}
Write-Output ('CANARY_ASSIGNMENT_ID='+$r.id)
Write-Output ('CANARY_ASSIGNMENT_STATE='+$r.state)
Write-Output ('CANARY_REPOSITORY='+$r.repository)
Write-Output ('CANARY_BRANCH='+$r.branch)
Write-Output ('CANARY_EXPECTED_HEAD='+$r.expectedHead)
Write-Output ('CANARY_IDEMPOTENCY='+$r.idempotencyKey)
Write-Output 'CANARY_ENQUEUE_ONCE_COMPLETED=True'
